// === Tab: mySketch ===
let currentScale
raindrops =[];
icicles = [];
let gravity = 0.0002

function setup() {
  createCanvas(350, 500);
  noStroke()
  for(let i=0; i<8; i++){
    icicles.push(new icicle)
  }
}

function draw() {
  background(200);


  for( let icicle of icicles) {
    icicle.update();
    icicle.show();
  }


  for (let Raindrop of raindrops) {
    Raindrop.update();
    Raindrop.show();
  }


}

class icicle{
  constructor(){
    this.x=random(0, width)
    this.y=random(30, 200)
    this.scaler= 1 - (this.y/2000)
    this.timer=round(random(50, 300))
  }
  update(){
    if(this.timer>=0){
      this.timer-=1
    }else{
      raindrops.push(new Raindrop(this.x, this.y, this.scaler));
      this.timer=random(100, 300)
    }   
  }

  show(){
    push()
  translate(this.x, this.y)
  scale(this.scaler)
  currentScale=this.scaler
  for(let i=0; i>-220; i-=5){
    fill(0, 200+i)
    ellipse(0-(i/10), i, i * .5, 2-(i/5))
  }
  pop()  
  }
}

class Raindrop{
  constructor(x, y, scaler){
    this.x=x
    this.y=y
    this.acc=0
    this.speed=0
    this.scaler= scaler
    this.timer=random(1, 800)
    this.r= 5 * this.scaler
  }

  update(){
      this.acc+=gravity
      this.speed+=this.acc
      this.y+=this.speed
    if (this.y > height) {
      let index = raindrops.indexOf(this);
      raindrops.splice(index, 1);
    }
  }
  show(){
    fill(255)
    ellipse(this.x, this.y, this.r)
  }
}

